import{_ as t,o,c as a,a1 as s}from"./chunks/framework.DIevSSiF.js";const m=JSON.parse('{"title":"Extension slots — the named capabilities the Method plugs into","description":"","frontmatter":{},"headers":[],"relativePath":"reference/slots.md","filePath":"reference/slots.md"}'),n={name:"reference/slots.md"};function i(r,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="extension-slots-—-the-named-capabilities-the-method-plugs-into" tabindex="-1">Extension slots — the named capabilities the Method plugs into <a class="header-anchor" href="#extension-slots-—-the-named-capabilities-the-method-plugs-into" aria-label="Permalink to &quot;Extension slots — the named capabilities the Method plugs into&quot;">​</a></h1><p>A <strong>slot</strong> is a named capability Shadow&#39;s method assumes it can reach, plus the default thing that fills it. This file is a declaration, never a record: nothing here is stamped, fetched, installed, or updated by any command. <code>shadow doctor</code> resolves every line at read time and reports present, absent, or stale — the same law as milestone status, which is derived at read time and never stored.</p><p>Shadow runs correctly with every slot empty. A slot says what the method would use if it were there; it never gates a cycle, claims a checkpoint, or carries proof. The computer board owns coordination and entity <code>PLAN.md</code> files own milestone/checkpoint detail and proof.</p><p>Override one binding with <code>SHADOW_SLOT_&lt;NAME&gt;</code> — an absolute path, or <code>off</code> to say the emptiness is deliberate. Flags and environment stay authoritative; there is no slot configuration file.</p><h2 id="the-slots" tabindex="-1">The slots <a class="header-anchor" href="#the-slots" aria-label="Permalink to &quot;The slots&quot;">​</a></h2><ul><li>slot memory | kind: skill | default: memory | fills: routed recall — the routing file that delegates where to look things up (static docs, semantic vectors, graph — per person); recall is a lead, never plan, proof, or ownership authority; re-verify at the attributed source | absent: mount a skill named memory in one of the three skill roots, or set SHADOW_SLOT_MEMORY=off</li><li>slot taste | kind: skill | default: taste | fills: the finished-quality grade on a human-visible surface and the voice of everything written or shown for humans — prose, briefs, PR text, explanation visuals — after it works and before anyone calls it done | absent: mount a skill named taste in one of the three skill roots, or set SHADOW_SLOT_TASTE=off</li></ul><h2 id="how-each-kind-resolves" tabindex="-1">How each kind resolves <a class="header-anchor" href="#how-each-kind-resolves" aria-label="Permalink to &quot;How each kind resolves&quot;">​</a></h2><p><strong>pack</strong> — a multi-skill plugin installed by a host&#39;s own plugin system (no shipped slot uses this kind today; the machinery retires next train if none appears). Read <code>~/.claude/plugins/cache/*/&lt;default&gt;/*/.claude-plugin/plugin.json</code> and compare its <code>name</code>. Present when it matches, and the detail is that manifest&#39;s <code>version</code>. One host surface only: Codex and Cursor plugin roots are not asserted, for the same reason doctor gives about Cursor user rules — asserting a path there would invent a convention.</p><p><strong>skill</strong> — one skill mounted in the three roots the installer writes. Look for <code>&lt;root&gt;/&lt;default&gt;/SKILL.md</code>. Present when at least one resolves.</p><p>A slot names only a capability Shadow itself reaches for. It never asserts anything about the rest of a machine: which memory backend or model tooling a person runs is their own configuration, and a check that failed over it would be Shadow policing software it does not use. The memory slot reaches only for the routing file it names — never the backend behind it.</p><h2 id="what-doctor-reports" tabindex="-1">What doctor reports <a class="header-anchor" href="#what-doctor-reports" aria-label="Permalink to &quot;What doctor reports&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>pack</th><th>skill</th></tr></thead><tbody><tr><td>present</td><td>PASS</td><td>PASS</td></tr><tr><td>absent</td><td>WARN, printing this line&#39;s <code>absent:</code> text</td><td>WARN, same</td></tr><tr><td>stale</td><td>FAIL</td><td>FAIL</td></tr><tr><td><code>off</code></td><td>PASS, naming the variable</td><td>PASS, same</td></tr></tbody></table><p><strong>Absent never fails.</strong> A slot is an optional capability; a machine that has not installed one is not a broken install. Present-but-wrong does fail, on the same reasoning the standing-goal check uses: a drifted copy is worse than none.</p><h2 id="why-this-is-not-a-second-store" tabindex="-1">Why this is not a second store <a class="header-anchor" href="#why-this-is-not-a-second-store" aria-label="Permalink to &quot;Why this is not a second store&quot;">​</a></h2><p>The file holds declaration only — no version stamp, no timestamp, no <code>last_checked</code>, no <code>installed: true</code>. A file that stamps nothing cannot drift from reality; it can only be wrong about intent, and wrong-about-intent is a reviewed git edit. Contrast a plugin manager&#39;s <code>installed_plugins.json</code>, which stores exactly the resolved state that <em>can</em> go stale.</p><p>Nothing coordinates through this file. <code>shadow throw</code>, <code>shadow accept</code>, and <code>shadow status</code> never read it. <code>shadow amp</code> may resolve only capabilities that the selected milestone explicitly named in <code>- tools:</code> and records the result inside its optional handoff block; it writes no state and absence never blocks the packet. Deleting this declaration therefore removes resolution detail, not rows, claims, priority, proof, or resume.</p><p>Declaration or resolution exceptions follow the same optional law: amp records a deterministic warning (exception type, never machine-specific error text) and falls back to the native host plus Shadow Method. An optional slot can never abort a resume packet.</p><p>Install adds no code: the declaration ships committed, so cloning defaults it.</p>',18)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
